// Package interactive provides TTY-related helpers shared between the cli
// and strategy packages without inducing an import cycle (strategy cannot
// import cli).
package interactive

import (
	"io"
	"os"
	"testing"

	"golang.org/x/term"
)

// EnvTestTTY is the env-var name for the force-interactive test override.
//   - EnvTestTTY=1 → CanPromptInteractively returns true.
//   - EnvTestTTY set to any other value → returns false.
//   - EnvTestTTY unset → real detection via testing.Testing(), agent
//     sentinels, CI, then /dev/tty probe.
const EnvTestTTY = "ENTIRE_TEST_TTY"

// CanPromptInteractively reports whether interactive confirmation prompts
// (huh forms, yes/no questions, etc.) can be shown. Returns false in CI,
// agent subprocesses that inherit a TTY but can't respond to prompts,
// and other environments without a controlling TTY.
//
// Precedence (first match wins):
//  1. EnvTestTTY=1 forces interactive ON; any other non-empty value forces OFF.
//  2. testing.Testing() — `go test` runs default to OFF so in-process tests
//     don't hang on developer terminals that happen to have a real /dev/tty.
//     Subprocess tests must spawn via execx.NonInteractive (or set EnvTestTTY).
//  3. Agent sentinels — vendor-set by agent subprocesses.
//  4. CI=<non-empty-non-false> — de-facto CI convention.
//  5. Git-hook context with a private session — when we run as a git hook (see
//     MarkGitHookContext) and our terminal session was created for this command
//     alone, git was run by a client capturing our output: lazygit gives `git
//     commit` its own pty and only renders what comes back, so a prompt there is
//     never answered and the commit hangs. See jobcontrol_unix.go.
//  6. /dev/tty probe, plus its terminal mode: a controlling terminal held in raw
//     mode belongs to a full-screen TUI (gitui, tig, …) that spawned us, not to
//     a shell we can prompt. See rawmode_unix.go.
func CanPromptInteractively() bool {
	if v := os.Getenv(EnvTestTTY); v != "" {
		return v == "1"
	}
	if testing.Testing() {
		return false
	}
	if isAgentSubprocessEnv() {
		return false
	}
	// CI=<non-empty> is the de-facto CI-provider convention (GitHub Actions,
	// CircleCI, GitLab, Travis, Buildkite). Self-hosted runners expose /dev/tty,
	// so the probe below isn't enough — an interactive prompt on CI hangs.
	// CI=false is the `is-ci` escape hatch for developers who need to override
	// an inherited value.
	if v := os.Getenv("CI"); v != "" && v != "false" {
		return false
	}

	// A git hook inherits whatever terminal the client that ran git left it, and
	// a TUI client hands us a private one it only reads from. This is scoped to
	// hook context because one-shot interactive invocations (`ssh -t host entire
	// enable`, `docker run -it … entire enable`) have the same private-session
	// shape but do forward the user's keystrokes.
	if inGitHookContext() && ttyIsPrivateSession() {
		return false
	}

	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return false
	}
	defer tty.Close()
	// Having a controlling terminal isn't enough — a TUI that spawned us holds
	// that same terminal in raw mode for its own screen and keys. See
	// rawmode_unix.go.
	return !ttyInRawMode(tty)
}

// UnderTest reports whether the process is running in a test context — either
// inside `go test` (testing.Testing()) or with EnvTestTTY explicitly set. Use
// to skip operations that read from the real terminal (e.g. opening /dev/tty)
// even when CanPromptInteractively() returns true.
func UnderTest() bool {
	return testing.Testing() || os.Getenv(EnvTestTTY) != ""
}

// isAgentSubprocessEnv reports whether the env indicates we're running inside
// an agent subprocess that inherited a TTY but can't respond to prompts:
//   - GEMINI_CLI=1: Gemini CLI shell tool (https://geminicli.com/docs/tools/shell/)
//   - COPILOT_CLI=1: Copilot CLI hook subprocesses (v0.0.421+)
//   - PI_CODING_AGENT=true: Pi Coding Agent shell tool
//   - GIT_TERMINAL_PROMPT=0: caller (CI, Factory AI Droid, etc.) asked git
//     to stop prompting; respect it from git-hook context too.
func isAgentSubprocessEnv() bool {
	return os.Getenv("GEMINI_CLI") != "" ||
		os.Getenv("COPILOT_CLI") != "" ||
		os.Getenv("PI_CODING_AGENT") != "" ||
		os.Getenv("GIT_TERMINAL_PROMPT") == "0"
}

// IsTerminalReader reports whether r is an *os.File backed by a terminal.
// It is useful when an explicitly interactive command needs to distinguish a
// human at stdin from an agent process that merely inherited a controlling TTY.
func IsTerminalReader(r io.Reader) bool {
	f, ok := r.(*os.File)
	if !ok {
		return false
	}
	return term.IsTerminal(int(f.Fd())) //nolint:gosec // G115: uintptr->int is safe for fd
}

// IsTerminalWriter reports whether w is an *os.File backed by a terminal.
// Use for deciding on color, pager, progress bars, or other writer-scoped
// TTY formatting. For "can I prompt the user?" use CanPromptInteractively.
func IsTerminalWriter(w io.Writer) bool {
	f, ok := w.(*os.File)
	if !ok {
		return false
	}
	return term.IsTerminal(int(f.Fd())) //nolint:gosec // G115: uintptr->int is safe for fd
}

// ShouldStyle reports whether ANSI-styled output (color, bold, rendered
// markdown) should be written to w. It is the single gate for writer-scoped
// styling decisions: NO_COLOR disables styling per https://no-color.org,
// legacy consoles that can't handle ANSI escapes are excluded, and otherwise
// the answer is whether w is a terminal.
func ShouldStyle(w io.Writer) bool {
	return shouldStyle(os.Getenv("NO_COLOR"), os.Getenv("TERM"), IsTerminalWriter(w))
}

// shouldStyle is the pure decision behind ShouldStyle, split out so tests can
// exercise the NO_COLOR/TERM gates with a simulated terminal writer — `go
// test` never has a real one, so testing through ShouldStyle would
// short-circuit on the terminal check and never reach the earlier gates.
func shouldStyle(noColor, term string, isTerminalWriter bool) bool {
	if noColor != "" {
		return false
	}
	if termLacksANSI(term) {
		return false
	}
	return isTerminalWriter
}

// termLacksANSI reports whether term identifies a legacy console that does
// not reliably handle ANSI escape sequences. The canonical case is
// TERM=cygwin: writing the ESC byte (0x1B) ends up rendered as the CP437
// glyph U+2190 LEFTWARDS ARROW ("←") instead of starting an SGR sequence, so
// styled output appears as literal text like "←[32m●←[m" (see GH #1267).
func termLacksANSI(term string) bool {
	return term == "cygwin"
}

package cli

import (
	"context"
	"fmt"
	"log/slog"
	"os"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent/external"
	"github.com/entireio/cli/cmd/entire/cli/checkpointpolicy"
	"github.com/entireio/cli/cmd/entire/cli/gitrepo"
	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/settings"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
	"github.com/entireio/cli/cmd/entire/cli/telemetry"
	"github.com/entireio/cli/cmd/entire/cli/versioncheck"
	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
	"github.com/entireio/cli/perf"

	"github.com/spf13/cobra"
)

// gitHooksDisabled is set by PersistentPreRunE when Entire is not set up or disabled.
// When true, all git hook commands return early without doing any work.
var gitHooksDisabled bool

// gitHookContext holds common state for git hook logging.
type gitHookContext struct {
	hookName string
	ctx      context.Context
	span     *perf.Span
	strategy *strategy.ManualCommitStrategy
}

// newGitHookContext creates a new git hook context with logging and a root perf span.
// The perf span ensures all perf.Start calls in strategy methods become child spans,
// producing a single perf log line per hook with a full timing breakdown.
// Callers must defer g.span.End() to emit the perf log.
func newGitHookContext(ctx context.Context, hookName string) *gitHookContext {
	ctx = logging.WithComponent(ctx, "hooks")
	ctx, span := perf.Start(ctx, hookName,
		slog.String("hook_type", "git"))
	g := &gitHookContext{
		hookName: hookName,
		ctx:      ctx,
		span:     span,
	}
	g.strategy = GetStrategy(ctx)
	return g
}

// logInvoked logs that the hook was invoked.
func (g *gitHookContext) logInvoked(extraAttrs ...any) {
	attrs := []any{
		slog.String("hook", g.hookName),
		slog.String("hook_type", "git"),
		slog.String("strategy", strategy.StrategyNameManualCommit),
	}
	logging.Debug(g.ctx, g.hookName+" hook invoked", append(attrs, extraAttrs...)...)
}

// logCompleted records the error on the perf span.
func (g *gitHookContext) logCompleted(err error) {
	g.span.RecordError(err)
}

func (g *gitHookContext) skipUnsupportedCheckpointPolicy() bool {
	// Callers return success when this is true because policy failures should
	// disable Entire checkpoint work, not make Git reject the user's operation.
	repo, err := gitrepo.OpenCurrent(g.ctx)
	if err != nil {
		return g.skipUnreadableCheckpointPolicy(err)
	}
	defer repo.Close()

	state, err := checkpointpolicy.ReadLocal(g.ctx, repo)
	if err != nil {
		return g.skipUnreadableCheckpointPolicy(err)
	}

	policy := state.Policy
	if checkpointpolicy.CanSatisfyPolicy(policy) {
		return false
	}

	logging.Warn(g.ctx, "checkpoint policy unsupported; skipping git hook",
		slog.String("checkpoint_version", policy.CheckpointVersion),
		slog.String("checkpoint_min_version", policy.CheckpointMinVersion))
	if interactive.CanPromptInteractively() {
		fmt.Fprint(os.Stderr, checkpointpolicy.UnsupportedPolicyMessage(
			policy,
			versioncheck.UpdateCommandForCurrentBinary(versioninfo.Version),
		))
	}
	emitCheckpointPolicyBlocked(g.ctx, telemetry.CheckpointPolicyBlockedEvent{
		Hook:                 g.hookName,
		HookType:             telemetry.PolicyBlockedHookTypeGit,
		Reason:               telemetry.PolicyBlockedReasonUnsupported,
		Outcome:              telemetry.PolicyBlockedOutcomeSkipped,
		CheckpointVersion:    policy.CheckpointVersion,
		CheckpointMinVersion: policy.CheckpointMinVersion,
	})
	return true
}

// skipUnreadableCheckpointPolicy warns, notifies the user, and reports the
// policy-blocked telemetry event for a hook whose checkpoint policy could not be
// read. It always returns true so callers skip Entire checkpoint work.
func (g *gitHookContext) skipUnreadableCheckpointPolicy(err error) bool {
	logging.Warn(g.ctx, "checkpoint policy read failed; skipping git hook",
		slog.String("error", err.Error()))
	if interactive.CanPromptInteractively() {
		fmt.Fprintf(os.Stderr, "[entire] Could not read checkpoint policy; skipping Entire checkpoint work: %v\n", err)
	}
	emitCheckpointPolicyBlocked(g.ctx, telemetry.CheckpointPolicyBlockedEvent{
		Hook:     g.hookName,
		HookType: telemetry.PolicyBlockedHookTypeGit,
		Reason:   telemetry.PolicyBlockedReasonUnreadable,
		Outcome:  telemetry.PolicyBlockedOutcomeSkipped,
	})
	return true
}

// initHookLogging initializes logging for hooks by finding the most recent session.
// Returns a cleanup function that should be deferred.
// If Entire is not set up or disabled, returns a no-op to avoid creating files.
func initHookLogging(ctx context.Context) func() {
	// Don't create any files if Entire is not set up or disabled.
	// This is checked here as defense-in-depth (also checked in PersistentPreRunE).
	if !settings.IsSetUpAndEnabled(ctx) {
		return func() {}
	}

	// Set up log level getter so logging can read from settings
	logging.SetLogLevelGetter(GetLogLevel)

	// Read session ID for the slog attribute (empty string is fine - log file is fixed)
	sessionID := strategy.FindMostRecentSession(ctx)
	if err := logging.Init(ctx, sessionID); err != nil {
		// Init failed - logging will use stderr fallback
		return func() {}
	}

	// Configure redaction once at startup: PII (opt-in), inline custom_redactions,
	// and rule packs discovered under .entire/redactors/. No-op if nothing is configured.
	strategy.EnsureRedactionConfigured()

	return logging.Close
}

// hookLogCleanup stores the cleanup function for hook logging.
// Set by PersistentPreRunE, called by PersistentPostRunE.
var hookLogCleanup func()

func newHooksGitCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:    "git",
		Short:  "Git hook handlers",
		Long:   "Commands called by git hooks. These delegate to the current strategy.",
		Hidden: true, // Internal command, not for direct user use
		PersistentPreRunE: func(cmd *cobra.Command, _ []string) error {
			ctx := cmd.Context()
			// Tell the prompt gate we're a git hook: the terminal we inherit
			// belongs to whatever ran git, which for a TUI client is a private pty
			// it only renders. Set unconditionally and before any early return so
			// every prompt in this process sees it.
			interactive.MarkGitHookContext()
			// Check if Entire is set up and enabled before doing any work.
			// This prevents global git hooks from doing anything in repos where
			// Entire was never enabled or has been disabled.
			if !settings.IsSetUpAndEnabled(ctx) {
				gitHooksDisabled = true
				return nil
			}
			// Discover external agent plugins so GetByAgentType works correctly
			// during condensation (e.g. post-commit). Without this, external agents
			// registered in the hook phase cannot be resolved here, causing token
			// usage and other agent-specific data to be missing from metadata.json.
			discoveryCtx, cancel := context.WithTimeout(ctx, 5*time.Second)
			defer cancel()
			external.DiscoverAndRegister(discoveryCtx)
			hookLogCleanup = initHookLogging(ctx)
			return nil
		},
		PersistentPostRunE: func(_ *cobra.Command, _ []string) error {
			if hookLogCleanup != nil {
				hookLogCleanup()
			}
			return nil
		},
	}

	cmd.AddCommand(newHooksGitPrepareCommitMsgCmd())
	cmd.AddCommand(newHooksGitCommitMsgCmd())
	cmd.AddCommand(newHooksGitPostCommitCmd())
	cmd.AddCommand(newHooksGitPostRewriteCmd())
	cmd.AddCommand(newHooksGitPrePushCmd())

	return cmd
}

func newHooksGitPrepareCommitMsgCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "prepare-commit-msg <commit-msg-file> [source]",
		Short: "Handle prepare-commit-msg git hook",
		Args:  cobra.RangeArgs(1, 2),
		RunE: func(cmd *cobra.Command, args []string) error {
			if gitHooksDisabled {
				return nil
			}

			commitMsgFile := args[0]
			var source string
			if len(args) > 1 {
				source = args[1]
			}

			g := newGitHookContext(cmd.Context(), "prepare-commit-msg")

